mapper.select:
select pay.payOrderId, pay.payRelId, pay.payNo, pay.payTime, pay.payAmount, pay.title, pay.remark, pay.payState, pay.queryTime, pay.tradeState, pay.payFallMessage , pay.createTime, pay.createUserId, pay.modifyTime, pay.modifyUserId from cf_payorder pay where 1=1
and pay.payState = #{payState}
order by pay.createTime desc
